import type { NodePgDatabase } from "drizzle-orm/node-postgres";
import type * as schema from "@/modules/database/schema";
import type { relations } from "@/modules/database/relations";

export type DrizzleDb = NodePgDatabase<typeof schema, typeof relations>;
export type DrizzleTx = Parameters<DrizzleDb["transaction"]>[0];

export interface IPostgresStore {
  get client(): DrizzleDb;
  run<T>(operation: () => Promise<T>, errorLabel?: string): Promise<T>;
  transaction<T>(
    fn: (tx: DrizzleTx) => Promise<T>,
    errorLabel?: string,
  ): Promise<T>;
}

import { drizzle } from "drizzle-orm/node-postgres";
import { config } from "@/lib/config";
import { tryCatch } from "@/lib/try-catch-wrapper";
import * as schema from "@/modules/database/schema";
import { relations } from "@/modules/database/relations";
import { db as defaultDb } from "@/modules/database/client";
import type { IPostgresStore, DrizzleDb, DrizzleTx } from "./pg-store.interface";

export class PostgresStore implements IPostgresStore {
  private _client: DrizzleDb;

  constructor(client?: DrizzleDb) {
    this._client = client ?? (defaultDb as DrizzleDb);
  }

  get client(): DrizzleDb {
    return this._client;
  }

  async run<T>(operation: () => Promise<T>, errorLabel?: string): Promise<T> {
    return tryCatch({
      ctx: operation,
      errorMessage: errorLabel ?? "DATABASE_OPERATION_FAILED",
    });
  }

  async transaction<T>(
    fn: (tx: DrizzleTx) => Promise<T>,
    errorLabel?: string,
  ): Promise<T> {
    return tryCatch({
      ctx: () => this._client.transaction(fn),
      errorMessage: errorLabel ?? "TRANSACTION_FAILED",
    });
  }
}

export type { IPostgresStore, DrizzleDb, DrizzleTx } from "./pg-store.interface";
export { PostgresStore } from "./pg-store";
export type { ICacheStore } from "./cache-store.interface";

import type { IPostgresStore } from "./stores/pg-store.interface";
import type { ICacheStore } from "./stores/cache-store.interface";

export abstract class CompositeRepository {
  protected readonly pg: IPostgresStore;
  protected readonly cache: ICacheStore;

  constructor(opts: {
    pg: IPostgresStore;
    cache: ICacheStore;
  }) {
    this.pg = opts.pg;
    this.cache = opts.cache;
  }

  /** Build consistent cache key from segments */
  protected cacheKey(...parts: string[]): string {
    return parts.join(":");
  }
}

export { CompositeRepository } from "./composite.repository";
export type { IPostgresStore, DrizzleDb, DrizzleTx } from "./stores";
export { PostgresStore } from "./stores";
export type { ICacheStore } from "./stores";

