  entryType: EntryType;
  createdAt: Date;
  updatedAt: Date | null;
}

export interface ILedgerRepository {
  create(entry: Omit<ILedgerEntryDTO, "id" | "createdAt" | "updatedAt">): Promise<ILedgerEntryDTO>;
  findById(entryId: TLedgerEntryId): Promise<ILedgerEntryDTO | null>;
