import { eq } from "drizzle-orm";
import { CompositeRepository, type IPostgresStore, type ICacheStore } from "@/lib/repository";
import { AccountsTable } from "@/modules/database/schema/transaction.repository";
import type { TBankAccountNumber, TUserId } from "@/types";
import type { IAccountDTO, IAccountRepository } from "./contracts";

type StoreOpts = { pg?: IPostgresStore; cache?: ICacheStore };

export class AccountRepository extends CompositeRepository implements IAccountRepository {
  constructor(opts?: StoreOpts) {
    super(opts);
  }

  private accountCacheKey(accountNumber: TBankAccountNumber): string {
    return this.cacheKey("account", accountNumber.toString());
  }

  private userAccountsCacheKey(userId: TUserId): string {
    return this.cacheKey("user-accounts", userId);
  }

  private toDTO(row: any): IAccountDTO {
    return { ...row, balance: Number(row.balance) };
  }

  async create(account: Omit<IAccountDTO, "createdAt" | "updatedAt">): Promise<IAccountDTO> {
    const result = await this.pg.run(async () => {
      const [row] = await this.pg.client
        .insert(AccountsTable)
        .values({
          ...account,
          balance: account.balance.toString(),
          createdAt: new Date(),
          updatedAt: null,
        })
        .returning();
      if (!row) throw new Error("Failed to create account");
      return this.toDTO(row);
    }, "FAILED_TO_CREATE_ACCOUNT");

    await this.cache.del(this.userAccountsCacheKey(result.userId));
    return result;
  }

  async findById(accountNumber: TBankAccountNumber): Promise<IAccountDTO | null> {
    return this.cache.getOrSet(this.accountCacheKey(accountNumber), () =>
      this.pg.run(async () => {
        const row = await this.pg.client.query.AccountsTable.findFirst({
          where: { accountNumber: { eq: accountNumber } },
        });
        return row ? this.toDTO(row) : null;
      }, "FAILED_TO_FIND_ACCOUNT_BY_ID"),
    3600);
  }

  async findByAccountNumber(accountNumber: TBankAccountNumber): Promise<IAccountDTO | null> {
    return this.findById(accountNumber);
  }

  async findByUserId(userId: TUserId): Promise<IAccountDTO[]> {
    return this.pg.run(async () => {
      const rows = await this.pg.client.query.AccountsTable.findMany({
        where: { userId: { eq: userId } },
      });
      return rows.map(this.toDTO);
    }, "FAILED_TO_FIND_ACCOUNTS_BY_USER");
  }

  async calculateNewBalance(accountNumber: TBankAccountNumber, amount: number): Promise<number> {
    return this.pg.run(async () => {
      const [row] = await this.pg.client
        .select()
        .from(AccountsTable)
        .where(eq(AccountsTable.accountNumber, accountNumber))
        .for("update")
        .execute();
      if (!row) throw new Error("Account not found");
      const newBalance = Number(row.balance) + amount;
      if (newBalance <= 0) throw new Error("Insufficient funds");
      return newBalance;
    }, "FAILED_TO_CALCULATE_BALANCE");
  }

  async adjustBalance(accountNumber: TBankAccountNumber, amount: number): Promise<number> {
    const newBalance = await this.pg.transaction(async (tx) => {
      const [row] = await tx
        .select()
        .from(AccountsTable)
        .where(eq(AccountsTable.accountNumber, accountNumber))
        .for("update")
        .execute();
      if (!row) throw new Error("Account not found");
      const nb = Number(row.balance) + amount;
      if (nb <= 0) throw new Error("Insufficient funds");
      await tx
        .update(AccountsTable)
        .set({ balance: nb.toString(), updatedAt: new Date() })
        .where(eq(AccountsTable.accountNumber, accountNumber))
        .execute();
      return nb;
    }, "FAILED_TO_ADJUST_BALANCE");

    await this.cache.del(this.accountCacheKey(accountNumber));
    return newBalance;
  }

  async checkBalance(accountNumber: TBankAccountNumber): Promise<IAccountDTO> {
    const account = await this.findById(accountNumber);
    if (!account) throw new Error("Account not found");
    return account;
  }

  async updateBalance(accountNumber: TBankAccountNumber, newBalance: number): Promise<void> {
    await this.pg.run(async () => {
      await this.pg.client
        .update(AccountsTable)
        .set({ balance: newBalance.toString(), updatedAt: new Date() })
        .where(eq(AccountsTable.accountNumber, accountNumber))
        .execute();
    }, "FAILED_TO_UPDATE_BALANCE");

    await this.cache.del(this.accountCacheKey(accountNumber));
  }
}

import { eq } from "drizzle-orm";
import { CompositeRepository, type IPostgresStore, type ICacheStore } from "@/lib/repository";
import { TransactionsTable } from "@/modules/database/schema/transaction.repository";
import type { TTransactionId, TUserId } from "@/types";
import type { ITransactionDTO, TransactionQuery, ITransactionRepository } from "./contracts";

type StoreOpts = { pg?: IPostgresStore; cache?: ICacheStore };

export class TransactionRepository extends CompositeRepository implements ITransactionRepository {
  constructor(opts?: StoreOpts) { super(opts); }

  private txCacheKey(id: TTransactionId): string {
    return this.cacheKey("transaction", id);
  }

  private userTxCacheKey(userId: TUserId): string {
    return this.cacheKey("user-transactions", userId);
  }

  async save(transaction: ITransactionDTO): Promise<void> {
    await this.pg.run(async () => {
      await this.pg.client.insert(TransactionsTable).values({
        ...transaction,
        createdAt: new Date(),
        updatedAt: new Date(),
      });
    }, "FAILED_TO_SAVE_TRANSACTION");
    await this.cache.del(this.userTxCacheKey(transaction.userId));
  }

  async update(transaction: ITransactionDTO): Promise<ITransactionDTO> {
    const updated = await this.pg.run(async () => {
      const [row] = await this.pg.client
        .update(TransactionsTable)
        .set({ ...transaction, updatedAt: new Date() })
        .where(eq(TransactionsTable.id, transaction.id))
        .returning();
      if (!row) throw new Error(`Transaction ${transaction.id} not found`);
      return row;
    }, "FAILED_TO_UPDATE_TRANSACTION");

    await this.cache.del(this.txCacheKey(updated.id));
    await this.cache.del(this.userTxCacheKey(updated.userId));
    return updated;
  }

  findById(transactionId: TTransactionId): Promise<ITransactionDTO | null> {
    return this.cache.getOrSet(this.txCacheKey(transactionId), () =>
      this.pg.run(async () => {
        const row = await this.pg.client.query.TransactionsTable.findFirst({
          where: { id: { eq: transactionId } },
        });
        return row ?? null;
      }, "FAILED_TO_FIND_TRANSACTION"),
    3600);
  }

  findByUserId(userId: TUserId): Promise<ITransactionDTO[]> {
    return this.cache.getOrSet(this.userTxCacheKey(userId), () =>
      this.pg.run(async () => {
        return await this.pg.client.query.TransactionsTable.findMany({
          where: { userId: { eq: userId } },
        });
      }, "FAILED_TO_FIND_TRANSACTIONS_BY_USER"),
    3600);
  }

  async failedTransactions(query: TransactionQuery): Promise<ITransactionDTO[]> {
    return this.pg.run(async () => {
      const { userId, accountNumber } = query;
      return await this.pg.client.query.TransactionsTable.findMany({
        where: {
          userId: { eq: userId },
          status: { eq: "failed" },
          ...(accountNumber
            ? {
                OR: [
                  { senderAccountNumber: { eq: accountNumber } },
                  { receiverAccountNumber: { eq: accountNumber } },
                ],
              }
            : {}),
        },
        orderBy: { createdAt: "asc" },
        limit: 10,
      });
    }, "FAILED_TO_GET_FAILED_TRANSACTIONS");
  }

  async successfulTransactions(query: TransactionQuery): Promise<ITransactionDTO[]> {
    return this.pg.run(async () => {
      const { userId, accountNumber } = query;
      return await this.pg.client.query.TransactionsTable.findMany({
        where: {
          userId: { eq: userId },
          status: { eq: "success" },
          ...(accountNumber
            ? {
                OR: [
                  { senderAccountNumber: { eq: accountNumber } },
                  { receiverAccountNumber: { eq: accountNumber } },
                ],
              }
            : {}),
        },
        orderBy: { createdAt: "desc" },
        limit: 10,
      });
    }, "FAILED_TO_GET_SUCCESSFUL_TRANSACTIONS");
  }
}

import { eq } from "drizzle-orm";
import { CompositeRepository, type IPostgresStore, type ICacheStore } from "@/lib/repository";
import { LedgerTable } from "@/modules/database/schema/ledger.repository";
import { ID } from "@/lib/ID";
import type { TLedgerEntryId, TTransactionId } from "@/types";
import type { ILedgerEntryDTO, EntryType, ILedgerRepository } from "./contracts";

type StoreOpts = { pg?: IPostgresStore; cache?: ICacheStore };

export class LedgerRepository extends CompositeRepository implements ILedgerRepository {
  constructor(opts?: StoreOpts) { super(opts); }

  private byTxCacheKey(transactionId: TTransactionId): string {
    return this.cacheKey("ledger-by-tx", transactionId);
  }

  private toDTO(row: any): ILedgerEntryDTO {
    return { ...row, amount: Number(row.amount) };
  }

  async create(entry: Omit<ILedgerEntryDTO, "id" | "createdAt" | "updatedAt">): Promise<ILedgerEntryDTO> {
    const newEntry = await this.pg.run(async () => {
      const [row] = await this.pg.client
        .insert(LedgerTable)
        .values({
          ...entry,
          id: ID.LedgerEntryId(),
          amount: BigInt(entry.amount),
          createdAt: new Date(),
          updatedAt: new Date(),
        })
        .returning();
      if (!row) throw new Error("Failed to create ledger entry");
      return this.toDTO(row);
    }, "FAILED_TO_CREATE_LEDGER_ENTRY");

    await this.cache.del(this.byTxCacheKey(newEntry.transactionId));
    return newEntry;
  }

  async findById(entryId: TLedgerEntryId): Promise<ILedgerEntryDTO | null> {
    return this.pg.run(async () => {
      const row = await this.pg.client.query.LedgerTable.findFirst({
        where: { id: { eq: entryId } },
      });
      return row ? this.toDTO(row) : null;
    }, "FAILED_TO_FIND_LEDGER_ENTRY");
  }

  findByTransactionId(transactionId: TTransactionId): Promise<ILedgerEntryDTO[]> {
    return this.cache.getOrSet(this.byTxCacheKey(transactionId), () =>
      this.pg.run(async () => {
        const rows = await this.pg.client.query.LedgerTable.findMany({
          where: { transactionId: { eq: transactionId } },
        });
        return rows.map(this.toDTO);
      }, "FAILED_TO_FIND_LEDGER_BY_TX"),
    3600);
  }

  async findByEntryType(entryType: EntryType): Promise<ILedgerEntryDTO[]> {
    return this.pg.run(async () => {
      const rows = await this.pg.client.query.LedgerTable.findMany({
        where: { entryType: { eq: entryType } },
        orderBy: { createdAt: "desc" },
      });
      return rows.map(this.toDTO);
    }, "FAILED_TO_FIND_LEDGER_BY_TYPE");
  }

  async update(entryId: TLedgerEntryId, updates: Partial<Omit<ILedgerEntryDTO, "id" | "createdAt">>): Promise<void> {
    const entry = await this.findById(entryId);
    const data: any = { ...updates, updatedAt: new Date() };
    if (updates.amount !== undefined) data.amount = BigInt(updates.amount);

    await this.pg.run(async () => {
      await this.pg.client.update(LedgerTable).set(data).where(eq(LedgerTable.id, entryId)).execute();
    }, "FAILED_TO_UPDATE_LEDGER_ENTRY");

    if (entry) await this.cache.del(this.byTxCacheKey(entry.transactionId));
  }

  async delete(entryId: TLedgerEntryId): Promise<void> {
    const entry = await this.findById(entryId);
    await this.pg.run(async () => {
      await this.pg.client.delete(LedgerTable).where(eq(LedgerTable.id, entryId)).execute();
    }, "FAILED_TO_DELETE_LEDGER_ENTRY");

    if (entry) await this.cache.del(this.byTxCacheKey(entry.transactionId));
  }
}

import { desc, eq } from "drizzle-orm";
import { CompositeRepository, type IPostgresStore, type ICacheStore } from "@/lib/repository";
import { TransactionOutboxTable } from "@/modules/database/schema/transaction-outbox.repository";
import { ID } from "@/lib/ID";
import type { TTransactionId } from "@/types";
import type { IOutboxEntry, IOutboxRepository } from "./contracts";

type StoreOpts = { pg?: IPostgresStore; cache?: ICacheStore };

export class OutboxRepository extends CompositeRepository implements IOutboxRepository {
  constructor(opts?: StoreOpts) { super(opts); }

  async create(entry: Omit<IOutboxEntry, "id" | "createdAt" | "updatedAt">): Promise<IOutboxEntry> {
    return this.pg.run(async () => {
      const [row] = await this.pg.client
        .insert(TransactionOutboxTable)
        .values({ id: ID.outboxId(), ...entry, published: false })
        .returning();
      if (!row) throw new Error("Failed to create outbox entry");
      return {
        id: row.id,
        transactionId: row.transactionId as TTransactionId,
        eventType: row.eventType,
        payload: row.payload as Record<string, any>,
        published: row.published,
        publishedAt: row.publishedAt,
        createdAt: row.createdAt,
        updatedAt: row.updatedAt,
      };
    }, "FAILED_TO_CREATE_OUTBOX_ENTRY");
  }

  async markAsPublished(transactionId: TTransactionId, publishedAt: Date = new Date()): Promise<void> {
    await this.pg.run(async () => {
      await this.pg.client
        .update(TransactionOutboxTable)
        .set({ published: true, publishedAt })
        .where(eq(TransactionOutboxTable.transactionId, transactionId));
    }, "FAILED_TO_MARK_OUTBOX_PUBLISHED");
  }

  async findUnpublished(limit: number = 100): Promise<IOutboxEntry[]> {
    return this.pg.run(async () => {
      const rows = await this.pg.client
        .select()
        .from(TransactionOutboxTable)
        .where(eq(TransactionOutboxTable.published, false))
        .orderBy(desc(TransactionOutboxTable.createdAt))
        .limit(limit);
      return rows.map((row) => ({
        id: row.id,
        transactionId: row.transactionId as TTransactionId,
        eventType: row.eventType,
        payload: row.payload as Record<string, any>,
        published: row.published,
        publishedAt: row.publishedAt,
        createdAt: row.createdAt,
        updatedAt: row.updatedAt,
      }));
    }, "FAILED_TO_FIND_UNPUBLISHED_OUTBOX");
  }
}

